//! Small permutation groups: permutations in one-line notation (images of 1 … n),
//! the group generated by a list of permutations (breadth-first closure, capped),
//! orbits, stabilisers and Burnside counting.

use std::collections::{HashSet, VecDeque};

use num_bigint::BigInt;
use num_integer::Integer;
use num_traits::{ToPrimitive, Zero};

use crate::domains::fieldkit::domain_err;
use crate::domains::util::int_arg;
use crate::error::{MathError, MathResult};
use crate::expr::{Expr, ExprNode};

/// Largest group built (|S₈| = 40320).
pub const MAX_GROUP: usize = 40_320;
/// Most points a permutation may move.
pub const MAX_POINTS: usize = 64;

/// A permutation of `0 … n−1` (index ↦ image).
pub type Perm = Vec<usize>;

/// Reads one permutation `(σ(1), …, σ(n))`.
pub fn perm_arg(op: &str, e: &Expr) -> MathResult<Perm> {
    let ExprNode::Tuple(v) = e.node() else {
        return Err(domain_err(
            op,
            format!("{e} is not a permutation (σ(1), …, σ(n))"),
        ));
    };
    let n = v.len();
    if n == 0 || n > MAX_POINTS {
        return Err(domain_err(
            op,
            format!("a permutation must move 1 … {MAX_POINTS} points"),
        ));
    }
    let mut seen = vec![false; n];
    let mut out = Vec::with_capacity(n);
    for x in v {
        let k = int_arg(op, x)?
            .to_usize()
            .filter(|k| (1..=n).contains(k))
            .ok_or_else(|| domain_err(op, format!("{e} is not a permutation of 1 … {n}")))?;
        if std::mem::replace(&mut seen[k - 1], true) {
            return Err(domain_err(
                op,
                format!("{e} repeats {k}, so it is not a permutation"),
            ));
        }
        out.push(k - 1);
    }
    Ok(out)
}

/// Reads generators: one permutation or a tuple of permutations (all on the same
/// number of points).
pub fn generators_arg(op: &str, e: &Expr) -> MathResult<Vec<Perm>> {
    let gens = match e.node() {
        ExprNode::Tuple(v) if v.iter().all(|x| matches!(x.node(), ExprNode::Tuple(_))) => v
            .iter()
            .map(|g| perm_arg(op, g))
            .collect::<MathResult<Vec<_>>>()?,
        _ => vec![perm_arg(op, e)?],
    };
    let n = gens[0].len();
    if gens.iter().any(|g| g.len() != n) {
        return Err(domain_err(
            op,
            "all permutations must act on the same number of points",
        ));
    }
    Ok(gens)
}

/// `a ∘ b` (apply b first).
pub fn compose(a: &[usize], b: &[usize]) -> Perm {
    b.iter().map(|&i| a[i]).collect()
}

/// The group generated by `gens`.
pub fn closure(gens: &[Perm]) -> MathResult<Vec<Perm>> {
    let n = gens.first().map_or(0, Vec::len);
    let id: Perm = (0..n).collect();
    let mut seen: HashSet<Perm> = HashSet::from([id.clone()]);
    let mut out = vec![id.clone()];
    let mut queue = VecDeque::from([id]);
    while let Some(g) = queue.pop_front() {
        for s in gens {
            let h = compose(s, &g);
            if seen.insert(h.clone()) {
                if out.len() >= MAX_GROUP {
                    return Err(MathError::TooLarge(format!(
                        "a group with more than {MAX_GROUP} elements"
                    )));
                }
                out.push(h.clone());
                queue.push_back(h);
            }
        }
    }
    Ok(out)
}

/// Number of cycles (fixed points count as cycles).
pub fn cycle_count(p: &[usize]) -> usize {
    let mut seen = vec![false; p.len()];
    let mut cycles = 0;
    for i in 0..p.len() {
        if !seen[i] {
            cycles += 1;
            let mut j = i;
            while !seen[j] {
                seen[j] = true;
                j = p[j];
            }
        }
    }
    cycles
}

/// Burnside: the number of colourings of the points with `k` colours up to the group,
/// `(1/|G|) Σ_g k^{c(g)}`.
pub fn burnside(group: &[Perm], k: &BigInt) -> MathResult<BigInt> {
    let total: BigInt = group
        .iter()
        .map(|g| num_traits::pow(k.clone(), cycle_count(g)))
        .sum();
    let order = BigInt::from(group.len());
    let (q, r) = total.div_rem(&order);
    if !r.is_zero() {
        return Err(MathError::Undefined(
            "a whole number of orbits (not a group?)".into(),
        ));
    }
    Ok(q)
}

/// The orbit of point `x` (0-based), sorted.
pub fn orbit(group: &[Perm], x: usize) -> Vec<usize> {
    let mut o: Vec<usize> = group.iter().map(|g| g[x]).collect();
    o.sort_unstable();
    o.dedup();
    o
}

/// The size of the stabiliser of point `x`.
pub fn stabilizer_order(group: &[Perm], x: usize) -> usize {
    group.iter().filter(|g| g[x] == x).count()
}

/// The rotations of an n-cycle (cyclic group C_n) as generators.
pub fn rotation(n: usize) -> Perm {
    (0..n).map(|i| (i + 1) % n).collect()
}

/// A reflection of an n-gon.
pub fn reflection(n: usize) -> Perm {
    (0..n).map(|i| (n - i) % n).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn groups_and_orbits() {
        // S₃ from a transposition and a 3-cycle; D₄ has order 8.
        let s3 = closure(&[vec![1, 0, 2], vec![1, 2, 0]]).unwrap();
        assert_eq!(s3.len(), 6);
        let d4 = closure(&[rotation(4), reflection(4)]).unwrap();
        assert_eq!(d4.len(), 8);
        assert_eq!(orbit(&d4, 0), vec![0, 1, 2, 3]);
        assert_eq!(stabilizer_order(&d4, 0), 2);
        // Necklaces of 4 beads in 2 colours up to rotation: 6 (OEIS A000031).
        let c4 = closure(&[rotation(4)]).unwrap();
        assert_eq!(burnside(&c4, &BigInt::from(2)).unwrap(), BigInt::from(6));
        // Up to rotation and reflection (bracelets): 6 too; for 6 beads 13 (OEIS A000029).
        let d6 = closure(&[rotation(6), reflection(6)]).unwrap();
        assert_eq!(burnside(&d6, &BigInt::from(2)).unwrap(), BigInt::from(13));
        let s9 = closure(&[rotation(9), vec![1, 0, 2, 3, 4, 5, 6, 7, 8]]);
        assert!(s9.is_err()); // |S₉| = 362880 is over the cap
    }

    proptest! {
        #[test]
        fn orbit_stabilizer(n in 2usize..7, x in 0usize..7) {
            prop_assume!(x < n);
            for g in [closure(&[rotation(n)]).unwrap(), closure(&[rotation(n), reflection(n)]).unwrap()] {
                prop_assert_eq!(orbit(&g, x).len() * stabilizer_order(&g, x), g.len());
            }
        }
    }
}
